# Generated by build.py from recipe.yml for recipe smtp-catch-a-duplicate-from-a-lost-reply. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'token.txt'), "control-token-0123456789abcdefghij")
[IO.File]::WriteAllText((Join-Path $PWD 'order.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Order 1042 confirmed`nMessage-ID: <order-1042@shop.example.com>`n`nThank you for order 1042.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tries.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh tries.sh TRACE. Waits (at most 10 s) until every exchange in surl's --trace-ascii`n# file has ended, then, for each SMTP exchange that reached DATA (a try), prints what the server`n# sent from its 354 on, each line after the bytes the server had sent by the end of it, and`n# where the server stored the message or cut the connection.`ntrace=`$1`ntries=0`nuntil [ `"`$(grep -c ' opened: ' `"`$trace`")`" -le `"`$(grep -c ' ended; ' `"`$trace`")`" ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 10 ]; then echo `"an exchange has not ended`" >&2; exit 1; fi`n  sleep 1`ndone`ntr -d '\r' < `"`$trace`" | awk '`n  / opened: smtp / { smtp[`$1] = 1 }`n  / => Send data, / { take = smtp[`$1] ? `$1 : `"`"; sent[`$1] += `$5; next }`n  / \* Message stored/ && (`$1 in try) { print `"try `" try[`$1] `": message stored`"; next }`n  / cut after / && (`$1 in try) { n = `$0; sub(/.* cut after /, `"`", n); sub(/ bytes.*/, `"`", n); print `"try `" try[`$1] `": cut after `" n `" bytes`"; next }`n  /^#/ { take = `"`"; next }`n  take != `"`" && /^[0-9a-f][0-9a-f][0-9a-f][0-9a-f]: / {`n    line = substr(`$0, 7)`n    if (!(take in try) && index(line, `"354 `") == 1) try[take] = ++count`n    if (take in try) print `"try `" try[take] `": `" sent[take] `" `" line`n  }'`n")
$server0 = Start-Process surl -ArgumentList '--trace-ascii', 'smtp.trace', '--mail-domain', 'example.com', '--mailbox', 'shop@example.com:shoppass', '--mailbox', 'ann@example.com:annpass', '--control', 'http://127.0.0.1:8082', '--control-token-file', 'token.txt', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -o NUL -w "%{http_code}\n" -H "Authorization: Bearer control-token-0123456789abcdefghij" -H "Content-Type: text/plain" -d "drop;scheme=smtp;after-bytes=320;close=graceful;times=1" http://127.0.0.1:8082/v1/faults && curl -sS --crlf -m 10 --retry 1 --retry-all-errors --retry-delay 1 -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml -w "%{response_code} %{num_retries}\n" smtp://127.0.0.1:8080/shop.example.com && curl -sS -u ann@example.com:annpass -X "UID SEARCH HEADER Message-ID <order-1042@shop.example.com>" imap://127.0.0.1:8081/INBOX } finally { Stop-Process $server0 }
